import{_ as t,o,c as a,a2 as d}from"./chunks/framework.Dsf4_p3t.js";const u=JSON.parse('{"title":"Native Tuning Layer","description":"","frontmatter":{},"headers":[],"relativePath":"guide/native-tuning.md","filePath":"guide/native-tuning.md","lastUpdated":1791194682000}'),i={name:"guide/native-tuning.md"};function n(r,e,c,s,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="native-tuning-layer" tabindex="-1">Native Tuning Layer <a class="header-anchor" href="#native-tuning-layer" aria-label="Permalink to &quot;Native Tuning Layer&quot;">​</a></h1><p>The native tuning layer lives in <code>neoflux/src/native/</code> (namespace <code>neoflux::native</code>) and is the <strong>only</strong> place in the framework allowed to talk to OS-specific low-level APIs — thread scheduling, timer resolution, CPU feature and cache-topology probing. Everything there is <strong>best-effort</strong>: on restricted systems (no privileges, exotic kernels, unsupported CPUs) it degrades to a safe no-op and logs once, never throwing and never failing the caller.</p><p>Most of the time you do not call it directly — the render and event loops already do. This page explains what each entry point does per platform, where the automatic hooks are, and when a manual call is worth it.</p><h2 id="the-entry-points" tabindex="-1">The entry points <a class="header-anchor" href="#the-entry-points" aria-label="Permalink to &quot;The entry points&quot;">​</a></h2><table tabindex="0"><thead><tr><th>API</th><th>Purpose</th><th>Cost</th><th>When to call</th></tr></thead><tbody><tr><td><code>TuneRenderThread()</code></td><td>Scheduling shaping for the render thread (raises priority / registers with the platform multimedia scheduler).</td><td>One-time, cheap</td><td>Automatic at the top of <code>RenderLoop</code> before the first GPU work.</td></tr><tr><td><code>TuneUiThread()</code></td><td>Scheduling shaping for the UI/event-loop thread (timer resolution + priority).</td><td>One-time, cheap</td><td>Automatic at the start of <code>EventLoop::Run()</code>.</td></tr><tr><td><code>PinThreadToBigCores()</code></td><td>Pin the calling thread to &quot;big&quot;/performance cores on big.LITTLE / hybrid topologies.</td><td>One-time</td><td>Automatic after <code>TuneRenderThread()</code>. Manual if you spawn your own worker on a P-core–sensitive path.</td></tr><tr><td><code>DetectCpuFeatures()</code></td><td>Snapshot of SIMD capabilities (<code>sse42</code>, <code>avx2</code>, <code>neon</code>, <code>neon_fp16</code>).</td><td>Trivial, repeated</td><td>Anywhere; results are informational and callers must keep a scalar fallback.</td></tr><tr><td><code>DetectCacheTopology()</code></td><td>Runtime cache geometry (<code>CacheInfo</code>: coherence line size + L1d/L2/L3 bytes).</td><td>Cheap (one-time probe)</td><td>Once at startup, or before sizing your own data structures.</td></tr><tr><td><code>PrefetchForRead(const void*)</code></td><td>One-line read prefetch hint.</td><td>Free (a single instruction)</td><td>In tight loops you own, one iteration ahead.</td></tr><tr><td><code>PrefetchForWrite(const void*)</code></td><td>One-line write prefetch hint (exclusive / prepare-for-store).</td><td>Free</td><td>Before a store into a newly claimed slot or slab.</td></tr><tr><td><code>VerifyCacheLineConfig()</code></td><td>Compares runtime line size against compile-time <code>config::kCacheLineSize</code>; logs a <strong>WARNING once</strong> if the hardware line is wider.</td><td>Cheap</td><td>Once at startup (debug/telemetry), after logging is initialised.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">All entry points are <code>noexcept</code></p><p>None of them can throw or abort. A failed OS call becomes a log line and a return to the default — you never need to guard a call site.</p></div><h2 id="runtime-configuration-gflags" tabindex="-1">Runtime configuration (gflags) <a class="header-anchor" href="#runtime-configuration-gflags" aria-label="Permalink to &quot;Runtime configuration (gflags)&quot;">​</a></h2><p>Every tuning attempt is configurable at runtime; the flags are defined in <code>neoflux/src/core/flags.cpp</code> and documented in the READMEs:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td><code>--native_tuning</code></td><td><code>true</code></td><td>Master switch: <code>false</code> turns every entry point below into a no-op.</td></tr><tr><td><code>--native_render_rt_priority</code></td><td><code>1</code></td><td>Linux/Android SCHED_FIFO priority for the render thread (1..99).</td></tr><tr><td><code>--native_thread_nice</code></td><td><code>-5</code></td><td>Linux/Android nice value for the render (fallback) and UI threads.</td></tr><tr><td><code>--native_bigcore_threshold_permille</code></td><td><code>950</code></td><td>Big-core frequency threshold in permille of the fastest core (500..1000).</td></tr><tr><td><code>--native_mmcss_profile</code></td><td><code>Games</code></td><td>Windows MMCSS profile name.</td></tr><tr><td><code>--native_timer_period_ms</code></td><td><code>1</code></td><td>Windows <code>timeBeginPeriod</code> resolution in ms (<code>0</code> = off).</td></tr></tbody></table><p>Out-of-range values are clamped, and every flag still degrades silently when the OS refuses — the flags only change what is <em>attempted</em>, never correctness.</p><h2 id="platform-behaviour-matrix" tabindex="-1">Platform behaviour matrix <a class="header-anchor" href="#platform-behaviour-matrix" aria-label="Permalink to &quot;Platform behaviour matrix&quot;">​</a></h2><p><code>✓</code> = implemented; <code>no-op</code> = deliberately does nothing on that platform.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Windows</th><th>Linux</th><th>Android</th><th>macOS</th><th>iOS</th></tr></thead><tbody><tr><td><code>TuneRenderThread</code></td><td>MMCSS &quot;Games&quot; profile, else <code>ABOVE_NORMAL</code></td><td><code>SCHED_FIFO</code> priority 1, else nice −5</td><td><code>SCHED_FIFO</code>→nice, else no-op</td><td>QoS <code>USER_INTERACTIVE</code></td><td>QoS <code>USER_INTERACTIVE</code></td></tr><tr><td><code>TuneUiThread</code></td><td>1 ms timer resolution + <code>ABOVE_NORMAL</code> process class</td><td>nice −5</td><td>nice −5 (usually denied)</td><td>no-op (already <code>USER_INTERACTIVE</code>)</td><td>no-op</td></tr><tr><td><code>PinThreadToBigCores</code></td><td><code>EfficiencyClass</code> via logic-processor topology</td><td><code>sched_setaffinity</code> on ≥95%-of-max-frequency cores</td><td>same as Linux</td><td>no-op (QoS drives clusters)</td><td>no-op</td></tr><tr><td><code>DetectCpuFeatures</code></td><td>cpuid / xgetbv</td><td>cpuid / <code>getauxval</code></td><td><code>getauxval</code></td><td><code>sysctl</code> (Intel) / ABI (Silicon)</td><td>ABI (Silicon)</td></tr><tr><td><code>DetectCacheTopology</code></td><td>cpuid leaf 1 + leaf 4</td><td>sysfs cache tree</td><td>sysfs cache tree</td><td><code>sysctl hw.*</code></td><td><code>sysctl hw.*</code></td></tr><tr><td><code>PrefetchForRead/Write</code></td><td><code>_mm_prefetch</code></td><td><code>__builtin_prefetch</code></td><td><code>__builtin_prefetch</code></td><td><code>__builtin_prefetch</code></td><td><code>__builtin_prefetch</code></td></tr><tr><td><code>VerifyCacheLineConfig</code></td><td>✓</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr></tbody></table><p>Every method is intrinsic-based: no hand-written inline assembly is used anywhere in this layer (cpuid is <code>__cpuid</code>/<code>__cpuidex</code>, prefetch is <code>__builtin_prefetch</code> / <code>_mm_prefetch</code>).</p><p>That statement is about <em>this</em> layer only. The framework does ship a small number of hand-written SIMD kernels -- they live one directory down, in <code>src/native/asm/</code>, and are reached through the C ABI rather than from here. See <a href="./native-asm">Hand-Written Assembly Kernels</a>.</p><h2 id="automatic-integration-points" tabindex="-1">Automatic integration points <a class="header-anchor" href="#automatic-integration-points" aria-label="Permalink to &quot;Automatic integration points&quot;">​</a></h2><p>You get the tuning for free in the normal path:</p><ul><li><strong><code>RenderLoop</code></strong> — calls <code>TuneRenderThread()</code> once at thread start, then <code>PinThreadToBigCores()</code>, before entering the frame loop. This is the thread whose scheduling latency directly becomes frame-pacing jitter.</li><li><strong><code>EventLoop::Run()</code></strong> — calls <code>TuneUiThread()</code> once at the top. On Windows this is what turns the default ~15.6 ms timer granularity into 1 ms, without which a 60 FPS <code>condition_variable::wait_for()</code> visibly stutters.</li><li><strong>Startup / telemetry</strong> — <code>DetectCpuFeatures()</code>, <code>DetectCacheTopology()</code>, and <code>VerifyCacheLineConfig()</code> are cheap and safe to call once after <code>google::InitGoogleLogging()</code>. The framework logs the detected topology at <code>INFO</code> and raises the cache-line warning (see below) if needed.</li></ul><h3 id="when-to-call-manually" tabindex="-1">When to call manually <a class="header-anchor" href="#when-to-call-manually" aria-label="Permalink to &quot;When to call manually&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Situation</th><th>Call</th></tr></thead><tbody><tr><td>You create a thread that does GPU-adjacent or latency-critical work.</td><td><code>TuneRenderThread()</code> (+ <code>PinThreadToBigCores()</code>).</td></tr><tr><td>You want an info-level dump of the cache geometry in your own bug report.</td><td><code>DetectCacheTopology()</code> + <code>VerifyCacheLineConfig()</code>.</td></tr><tr><td>You own a lock-free / cache-sensitive data structure and want to size padding from the real line size.</td><td><code>DetectCacheTopology().line_size</code>.</td></tr><tr><td>You are streaming through a buffer in a hot loop you control.</td><td><code>PrefetchForRead()</code> / <code>PrefetchForWrite()</code> one iteration ahead.</td></tr><tr><td>You target bare-metal or a non-desktop platform and want to confirm what actually took effect.</td><td>Read the <code>native:</code> log lines — every path logs its outcome once.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Do not call the tuning functions per frame</p><p>They are for one-time thread/process shaping. Calling <code>PinThreadToBigCores()</code> in a loop fights the scheduler and can <em>hurt</em> throughput. Call once, at thread startup.</p></div><h2 id="cache-line-sizing-and-the-compile-time-config" tabindex="-1">Cache-line sizing and the compile-time config <a class="header-anchor" href="#cache-line-sizing-and-the-compile-time-config" aria-label="Permalink to &quot;Cache-line sizing and the compile-time config&quot;">​</a></h2><p><code>config::kCacheLineSize</code> (see <code>neoflux/include/neoflux/core/config.h</code>) is the <strong>compile-time</strong> alignment used to pad the SPSC ring queue head/tail into separate cache lines. It defaults to 64 and can be overridden at configure time:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNEOFLUX_CACHE_LINE_SIZE=128</span></span></code></pre></div><p>The runtime <code>DetectCacheTopology()</code> / <code>VerifyCacheLineConfig()</code> pair exists to catch the case where the compile-time value is <em>narrower</em> than the hardware line. The critical example is the <strong>Apple M series</strong>, whose L1 data cache coherence line is <strong>128 bytes</strong>: a queue padded to 64 bytes can land two adjacent objects on one line, so the producer and consumer still bounce that line between cores — false sharing survives the padding. On any Apple Silicon target, build with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNEOFLUX_CACHE_LINE_SIZE=128</span></span></code></pre></div><p><code>VerifyCacheLineConfig()</code> compares <code>CacheInfo::line_size</code> with <code>config::kCacheLineSize</code> and logs <strong>at most once</strong>:</p><table tabindex="0"><thead><tr><th>Runtime vs compile-time</th><th>Logged</th></tr></thead><tbody><tr><td>runtime <strong>&gt;</strong> compile-time</td><td><code>WARNING</code> — alignment insufficient, false-sharing risk, with the exact <code>-DNEOFLUX_CACHE_LINE_SIZE=</code> fix.</td></tr><tr><td>runtime <strong>==</strong> compile-time</td><td><code>INFO</code> — matched.</td></tr><tr><td>runtime <strong>&lt;</strong> compile-time</td><td><code>INFO</code> — conservative (safe, slight memory cost).</td></tr><tr><td>probe unavailable (no sysfs, unknown CPU)</td><td><code>INFO</code> — cache line assumed 64 B; no comparison.</td></tr></tbody></table><p>See <a href="./configuration">Configuration</a> for the full constant reference.</p><h2 id="verifying-what-happened" tabindex="-1">Verifying what happened <a class="header-anchor" href="#verifying-what-happened" aria-label="Permalink to &quot;Verifying what happened&quot;">​</a></h2><p>Every path logs exactly once, prefixed <code>native:</code>. A healthy desktop run looks like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I native: cache topology detected -- line=64B L1d=49152B L2=1310720B L3=56623104B</span></span>
<span class="line"><span>I native: compile-time cache line matches runtime (64B)</span></span>
<span class="line"><span>I native: render thread -&gt; SCHED_FIFO prio=1</span></span>
<span class="line"><span>I native: ui thread -&gt; nice -5</span></span></code></pre></div><p>On a 128-byte-line machine with a 64-byte build you would instead see:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>W native: runtime cache line (128B) exceeds compile-time</span></span>
<span class="line"><span>  config::kCacheLineSize (64B); SPSC queue head/tail may still share a</span></span>
<span class="line"><span>  coherence line -&gt; false sharing. Rebuild with</span></span>
<span class="line"><span>  -DNEOFLUX_CACHE_LINE_SIZE=128 to fix it.</span></span></code></pre></div><p>Absence of a <code>native:</code> line is never an error — it means the platform path was a deliberate no-op (for example, core pinning on Apple, where QoS already drives cluster placement).</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./configuration">Configuration</a> — <code>config::kCacheLineSize</code> and the other compile-time constants.</li><li><a href="./debugging">Debugging &amp; Tuning</a> — logging flags and the render-queue back-pressure story.</li><li><a href="./cross-platform">Cross-Platform</a> — how the per-platform translation units are selected at configure time.</li><li><a href="./native-asm">Hand-Written Assembly Kernels</a> -- the assembly SIMD kernels in <code>src/native/asm/</code>, and why they are not written with intrinsics.</li></ul><hr><p><em>Available since NeoFlux 0.3.1-alpha + the neoflux-fix patch set.</em></p>`,39)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
